INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_TWELFTH_ADJECTIVE','Clockwork');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_TWELFTH_CHIME','THE GRAND CHIME!');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_TWELFTH_CHIME_HELP','The clocks have synchronized! All cities receive +75% [ICON_PRODUCTION] Production and +50% [ICON_RESEARCH] Science this turn. Municipal Clocktowers add +2 flat Production. The next Grand Chime is in 6 turns.');
