INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_TWELFTH_CITY_8','Chimefall');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_TWELFTH_CITY_9','Twelve Bells');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_TWELFTH_CIV','The Twelfth Hour');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_TWELFTH_CIV5_HEADING_1','The Accord of Seconds');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_TWELFTH_CIV5_TEXT_1','The Twelfth Hour began when distant workshops agreed upon a single noon. Before the Accord of Seconds, no two city clocks agreed: trains waited at empty platforms, experiments ended too soon, and foundries poured into unready molds. A network of observatories and municipal pendulums replaced those quarrels with a shared measure.[NEWLINE][NEWLINE]Every citizen now keeps a precise schedule. Factories exchange standardized parts, researchers publish observations against the Grand Clock, and schools teach the care of an escapement alongside letters. Every sixth turn their separate preparations converge in the Grand Chime, an extraordinary interval of synchronized work and discovery.[NEWLINE][NEWLINE]Their mastery is organizational, not supernatural. A clock cannot grant another day; it can help a society use the day it has. The Twelfth Hour is an original fictional industrial civilization.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_TWELFTH_CIV_PEDIA','The Twelfth Hour began when distant workshops agreed upon a single noon. Before the Accord of Seconds, no two city clocks agreed: trains waited at empty platforms, experiments ended too soon, and foundries poured into unready molds. A network of observatories and municipal pendulums replaced those quarrels with a shared measure.[NEWLINE][NEWLINE]Every citizen now keeps a precise schedule. Factories exchange standardized parts, researchers publish observations against the Grand Clock, and schools teach the care of an escapement alongside letters. Every sixth turn their separate preparations converge in the Grand Chime, an extraordinary interval of synchronized work and discovery.[NEWLINE][NEWLINE]Their mastery is organizational, not supernatural. A clock cannot grant another day; it can help a society use the day it has. The Twelfth Hour is an original fictional industrial civilization.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_TWELFTH_DAWN','Keeper of Seconds, the hands of eternity turn once more.[NEWLINE][NEWLINE]Others measure greatness in gold, territory and conquest. Your people measure it in moments.[NEWLINE][NEWLINE]Your clocks have synchronized. Your workshops stand ready. Your scholars await the next stroke of the Grand Clock.[NEWLINE][NEWLINE]Will you command the passage of time, or become another civilization forgotten by it?');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_TWELFTH_DEFEAT_1','Even the grandest clock must eventually... stop.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_TWELFTH_DUMMY','Grand Chime');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_TWELFTH_DUMMY_HELP','Automatically synchronized with the Grand Clock; cannot be constructed or purchased.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_TWELFTH_GREETING_1','Greetings, traveller. You have arrived precisely when expected. I am the Keeper of Seconds. May our meeting prove a productive use of time.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_TWELFTH_KEEPER_HEADING_1','A Precisely Scheduled Mystery');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_TWELFTH_KEEPER_LIVED','The Synchronized Age');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_TWELFTH_KEEPER_NAME','The Keeper of Seconds');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_TWELFTH_KEEPER_SUBTITLE','Custodian of the Grand Clock');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_TWELFTH_KEEPER_TEXT_1','No surviving register records the Keeper of Seconds taking office. The oldest municipal ledger simply notes that the Keeper arrived on time. Cloaked among gears and celestial instruments, this mysterious figure presides over the Grand Clock and the public standards from which every lesser clock is set.[NEWLINE][NEWLINE]The Keeper demands punctuality from ministries and generals alike, but regards rest as part of a well-made schedule. Schools, workshops and observatories receive equal attention: knowledge plans the mechanism, industry builds it, and culture gives its motion purpose. Those who threaten the clockwork cities discover that their defenders have already rehearsed the response.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_TWELFTH_KEEPER_TITLES_1','The Keeper of Seconds');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_TWELFTH_LEADER','The Keeper of Seconds');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_TWELFTH_LEADER_PEDIA','No surviving register records the Keeper of Seconds taking office. The oldest municipal ledger simply notes that the Keeper arrived on time. Cloaked among gears and celestial instruments, this mysterious figure presides over the Grand Clock and the public standards from which every lesser clock is set.[NEWLINE][NEWLINE]The Keeper demands punctuality from ministries and generals alike, but regards rest as part of a well-made schedule. Schools, workshops and observatories receive equal attention: knowledge plans the mechanism, industry builds it, and culture gives its motion purpose. Those who threaten the clockwork cities discover that their defenders have already rehearsed the response.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_TWELFTH_PEACE_1','Let us set aside the hour of war. Our clocks shall mark a common peace, beginning now.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_TWELFTH_PROMOTION','Disciplined Pendulum');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_TWELFTH_PROMOTION_HELP','+1 [ICON_MOVES] Movement. +15% Combat Strength in friendly territory when attacking or defending. Retained on upgrade.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_TWELFTH_SHORT','The Twelfth Hour');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_TWELFTH_SPY_1','Silent Tick');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_TWELFTH_SPY_10','Last Stroke');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_TWELFTH_SPY_2','Second Hand');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_TWELFTH_SPY_3','Escapement');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_TWELFTH_SPY_4','Night Watch');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_TWELFTH_SPY_5','Hidden Gear');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_TWELFTH_SPY_6','Minute Mark');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_TWELFTH_SPY_7','Quiet Chime');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_TWELFTH_SPY_8','False Noon');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_TWELFTH_SPY_9','Balance Wheel');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_TWELFTH_STRATEGY','Plan around turns 6, 12, 18 and every sixth turn thereafter. Grow several cities to multiply the Grand Chime, develop Science infrastructure, and time important construction around its Production surge. Municipal Clocktowers preserve Workshop benefits and add Culture plus Chime Production. Pendulum Guards reinforce friendly territory quickly and keep their bonuses on upgrade. Favor Science, then industry-supported Domination; Culture and Diplomacy remain viable.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_TWELFTH_TOWER','Municipal Clocktower');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_TWELFTH_TOWER_HELP','Replaces Workshop, retaining ALL its normal Community Patch benefits. +1 [ICON_CULTURE] Culture permanently. During the Grand Chime only, adds +2 flat [ICON_PRODUCTION] Production, which participates in normal city yield modifiers.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_TWELFTH_TOWER_PEDIA','A Municipal Clocktower is workshop, public calendar and civic monument. Beneath its polished brass dial, engineers compare factory regulators against the municipal pendulum. Its bells divide work from rest and summon the city to shared festivals. During a Grand Chime every district releases its prepared work together.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_TWELFTH_TOWER_STRATEGY','Raise Clocktowers in productive cities before the sixth turn of each cycle. Their Culture is permanent; the extra two base Production arrives only with the Chime. Existing Workshop specialists, prerequisites and modifiers remain in force.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_TWELFTH_TRAIT','When the Clock Strikes');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_TWELFTH_TRAIT_HELP','Every sixth played turn (6, 12, 18...), the Grand Chime grants ALL your cities +75% [ICON_PRODUCTION] Production and +50% [ICON_RESEARCH] Science for one turn. The cycle follows the saved game turn, at every game speed. The first five turns are normal.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_TWELFTH_UNIT','Pendulum Guard');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_TWELFTH_UNIT_HELP','Replaces Pikeman and retains its normal Community Patch characteristics and promotions. +1 [ICON_MOVES] Movement and +15% Combat Strength when fighting in friendly territory. Both bonuses are retained on upgrade.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_TWELFTH_UNIT_PEDIA','The Pendulum Guard drill to a metronome that never pauses. Their polearms carry a counterweight beneath the blade, and their midnight-blue cloaks mark the watch to which they belong. A guard leaves one gate as another arrives: neither haste nor hesitation may interrupt the schedule. On the battlefield they use the standard Pikeman model.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_TWELFTH_UNIT_STRATEGY','Use the extra Movement to reinforce threatened clockwork cities. Fight in friendly territory to gain the strength bonus on attack and defense. Upgraded veterans keep their disciplined response.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_TWELFTH_WAR_1','Your final hour has been scheduled. I assure you, we are never late.');
